        ?route a tro:Line .
        ?route tro:abbreviation ?routeName .
        ?route tro:fullTitle ?routeLongName .
    }
}
GROUP BY ?trip ?tripShortName ?headsign ?routeName ?routeLongName
HAVING (MIN(?leaveTime) >= "00:00:00" && MIN(?leaveTime) < "01:00:00")

